files.content:
*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  inline-size: 100dvi;
  block-size: 100dvb;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background-color: black;
}

.sky {
  position: absolute;
  z-index: 1;
  inline-size: 100%;
  block-size: 50%;
  opacity: 0.52;
  inset-block-start: 0;
  inset-inline-end: 0;
  background-image: linear-gradient(to top, rgb(249 251 240) 10%, rgb(215 253 254) 20%, rgb(167 222 253) 40%, rgb(110 175 255) 100%);
}

.horizon {
  position: absolute;
  z-index: 1;
  inline-size: 100%;
  block-size: 50%;
  opacity: 0.99;
  background-repeat: no-repeat;
  inset-block-start: 0;
  inset-inline-end: 0;
  background-image: linear-gradient(to top, rgb(212 87 43 / 0.9) 0%, rgb(246 149 52 / 0.8) 20%, rgb(24 75 106 / 0) 100%);
}

.water {
  position: absolute;
  z-index: 2;
  inline-size: 100%;
  block-size: 50%;
  overflow: hidden;
  background-repeat: no-repeat;
  inset-block-end: 0;
  inset-inline-end: 0;
  background-image: linear-gradient(to top, rgb(0 25 45) 0%, rgb(14 71 117) 35%, rgb(26 126 174) 70%, rgb(62 168 220) 100%);
}
